CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0, head_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE workspace_revisions (workspace_id TEXT NOT NULL REFERENCES workspaces(id), revision INTEGER NOT NULL, PRIMARY KEY(workspace_id,revision));
CREATE TABLE api_keys (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), label TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','reviewer','viewer')), digest TEXT NOT NULL UNIQUE, prefix TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL, UNIQUE(workspace_id,id));
CREATE TABLE accounts (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, currency TEXT NOT NULL, institution TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(workspace_id,id), UNIQUE(workspace_id,name));
CREATE TABLE imports (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, account_id TEXT NOT NULL, side TEXT NOT NULL CHECK(side IN ('bank','ledger')), filename TEXT NOT NULL, row_count INTEGER NOT NULL, digest TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(workspace_id,id), UNIQUE(workspace_id,account_id,side,digest), FOREIGN KEY(workspace_id,account_id) REFERENCES accounts(workspace_id,id));
CREATE TABLE transactions (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, account_id TEXT NOT NULL, import_id TEXT NOT NULL, side TEXT NOT NULL CHECK(side IN ('bank','ledger')), date TEXT NOT NULL, amount INTEGER NOT NULL, currency TEXT NOT NULL, description TEXT NOT NULL, reference TEXT NOT NULL, external_id TEXT NOT NULL, fingerprint TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(workspace_id,id), UNIQUE(workspace_id,account_id,side,fingerprint), FOREIGN KEY(workspace_id,account_id) REFERENCES accounts(workspace_id,id), FOREIGN KEY(workspace_id,import_id) REFERENCES imports(workspace_id,id));
CREATE UNIQUE INDEX transaction_external_id ON transactions(workspace_id,account_id,side,external_id) WHERE external_id != '';
CREATE TABLE rules (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, account_id TEXT NOT NULL, name TEXT NOT NULL, tolerance INTEGER NOT NULL CHECK(tolerance BETWEEN 0 AND 10000), date_window INTEGER NOT NULL CHECK(date_window BETWEEN 0 AND 14), reference_mode TEXT NOT NULL CHECK(reference_mode IN ('prefer','require','ignore')), min_score INTEGER NOT NULL CHECK(min_score BETWEEN 40 AND 100), enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,account_id) REFERENCES accounts(workspace_id,id));
CREATE TABLE runs (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, account_id TEXT NOT NULL, rule_id TEXT NOT NULL, rule_snapshot TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('review','finalized')), revision INTEGER NOT NULL DEFAULT 0, created_by TEXT NOT NULL, created_at TEXT NOT NULL, finalized_at TEXT, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,account_id) REFERENCES accounts(workspace_id,id), FOREIGN KEY(workspace_id,rule_id) REFERENCES rules(workspace_id,id));
CREATE TABLE run_transactions (workspace_id TEXT NOT NULL, run_id TEXT NOT NULL, transaction_id TEXT NOT NULL, PRIMARY KEY(workspace_id,run_id,transaction_id), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id), FOREIGN KEY(workspace_id,transaction_id) REFERENCES transactions(workspace_id,id));
CREATE TABLE matches (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, run_id TEXT NOT NULL, bank_id TEXT NOT NULL, ledger_id TEXT NOT NULL, score INTEGER NOT NULL, variance INTEGER NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('proposed','approved','rejected')), note TEXT NOT NULL DEFAULT '', reviewed_by TEXT, reviewed_at TEXT, UNIQUE(workspace_id,run_id,bank_id), UNIQUE(workspace_id,run_id,ledger_id), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id), FOREIGN KEY(workspace_id,bank_id) REFERENCES transactions(workspace_id,id), FOREIGN KEY(workspace_id,ledger_id) REFERENCES transactions(workspace_id,id));
CREATE TABLE audit_events (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), sequence INTEGER NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, payload TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(workspace_id,sequence));
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'audit is immutable'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'audit is immutable'); END;
CREATE INDEX transaction_feed ON transactions(workspace_id,account_id,date DESC,id DESC);
CREATE INDEX import_feed ON imports(workspace_id,created_at DESC);
CREATE INDEX run_feed ON runs(workspace_id,created_at DESC);
CREATE INDEX match_queue ON matches(workspace_id,run_id,status);
